script:
/* =========================================================
   DIFF SYSTEM RELATED PRODUCTS — TIGHT SPACING
   ========================================================= */

/* Reduce overall section padding */
.related-product {
    padding: 35px 45px !important;
}


/* Reduce heading spacing */
.related-heading {
    margin-bottom: 18px !important;
}


/* Make the whole grid compact */
.related-content {
    column-gap: 25px !important;
    row-gap: 12px !important;
}


/* =========================================================
   PRODUCT 1 — COMPACT
   ========================================================= */

/* Category */
.related-content > *:nth-child(1) {
    margin: 0 0 5px 0 !important;
    padding: 0 !important;
}

/* Title */
.related-content > *:nth-child(2) {
    margin: 0 0 8px 0 !important;
    padding: 0 !important;
}

/* Description */
.related-content > *:nth-child(4) {
    margin: 0 !important;
    padding: 0 !important;
}


/* =========================================================
   PRODUCT 2 — COMPACT
   ========================================================= */

/* Category */
.related-content > *:nth-child(5) {
    margin: 0 0 5px 0 !important;
    padding: 0 !important;
}

/* Title */
.related-content > *:nth-child(6) {
    margin: 0 0 8px 0 !important;
    padding: 0 !important;
}

/* Description */
.related-content > *:nth-child(8) {
    margin: 0 !important;
    padding: 0 !important;
}


/* =========================================================
   CATEGORY
   ========================================================= */

.related-eyebrow {
    margin: 0 0 5px 0 !important;

    font-size: 8px !important;

    line-height: 1.2 !important;
}


/* =========================================================
   TITLE
   ========================================================= */

.related-title {
    margin: 0 !important;

    font-size: 19px !important;

    line-height: 1.2 !important;
}


/* =========================================================
   DESCRIPTION
   ========================================================= */

.related-description {
    margin: 0 !important;

    font-size: 12px !important;

    line-height: 1.4 !important;

    max-width: 500px !important;
}


/* =========================================================
   IMAGE
   ========================================================= */

.related-content > *:nth-child(3),
.related-content > *:nth-child(7) {

    height: 190px !important;

    padding: 10px !important;

    margin: 0 !important;
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 600px) {

    .related-product {
        padding: 25px 20px !important;
    }

    .related-content {
        gap: 10px !important;
    }

    .related-title {
        font-size: 18px !important;
    }

    .related-description {
        font-size: 12px !important;
    }

    .related-content > *:nth-child(3),
    .related-content > *:nth-child(7) {
        height: 180px !important;
    }
}

/* =========================================================
   RELATED PRODUCTS — COMPLETE FINAL CSS
   ========================================================= */


/* =========================================================
   MAIN RELATED PRODUCTS SECTION
   ========================================================= */

#related-products {
    width: 1100px !important;
    max-width: calc(100% - 80px) !important;

    margin: 55px auto 40px auto !important;

    padding: 30px !important;

    box-sizing: border-box !important;

    background: #eef1ef !important;

    border: 1px solid #dfe4e1 !important;
    border-radius: 8px !important;

    display: grid !important;

    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;

    gap: 24px !important;

    align-items: stretch !important;

    overflow: visible !important;
}


/* =========================================================
   RELATED PRODUCTS HEADING
   ========================================================= */

.related-heading {
    grid-column: 1 / -1 !important;

    margin: 0 !important;
    padding: 0 !important;

    color: #071b2b !important;

    font-size: 18px !important;
    line-height: 1.2 !important;

    font-weight: 600 !important;
}


/* =========================================================
   RELATED PRODUCT CARD
   ========================================================= */

.related-product {
    width: 100% !important;
    max-width: none !important;

    margin: 0 !important;
    padding: 24px !important;

    box-sizing: border-box !important;

    background: #ffffff !important;

    border: 1px solid #dfe4e1 !important;
    border-radius: 8px !important;

    display: grid !important;

    grid-template-columns: 1fr 1fr !important;

    grid-template-rows: auto 1fr !important;

    column-gap: 20px !important;
    row-gap: 14px !important;

    align-items: start !important;

    overflow: hidden !important;

    transition:
        transform 0.3s ease,
        border-color 0.3s ease,
        box-shadow 0.3s ease !important;
}


/* =========================================================
   ORANGE HOVER
   ========================================================= */

.related-product:hover {
    transform: translateY(-5px) !important;

    border-color: #f28c28 !important;

    box-shadow:
        0 10px 24px rgba(242, 140, 40, 0.18) !important;
}


/* =========================================================
   CATEGORY / EYEBROW
   ========================================================= */

.related-eyebrow {
    grid-column: 1 !important;
    grid-row: 1 !important;

    width: 100% !important;

    margin: 0 !important;
    padding: 0 !important;

    color: #71859a !important;

    font-size: 9px !important;
    line-height: 1.3 !important;

    font-weight: 600 !important;

    letter-spacing: 1.3px !important;

    text-transform: uppercase !important;

    transition: color 0.25s ease !important;
}


.related-product:hover .related-eyebrow {
    color: #f28c28 !important;
}


/* =========================================================
   TITLE
   ========================================================= */

.related-title {
    grid-column: 2 !important;
    grid-row: 1 !important;

    width: 100% !important;

    margin: 0 !important;
    padding: 0 !important;

    color: #071b2b !important;

    font-size: 30px !important;
    line-height: 1.1 !important;

    font-weight: 700 !important;

    letter-spacing: -0.5px !important;

    text-align: left !important;

    transition: color 0.25s ease !important;
}


.related-product:hover .related-title {
    color: #f28c28 !important;
}


/* =========================================================
   IMAGE
   ========================================================= */

.related-image {
    grid-column: 1 !important;
    grid-row: 2 !important;

    display: block !important;

    width: 100% !important;
    height: 190px !important;

    margin: 0 !important;
    padding: 10px !important;

    box-sizing: border-box !important;

    background: #f8faf9 !important;

    border: 1px solid #d8ddda !important;
    border-radius: 6px !important;

    object-fit: contain !important;
    object-position: center !important;

    transition:
        transform 0.3s ease,
        border-color 0.3s ease,
        background 0.3s ease !important;
}


.related-product:hover .related-image {
    transform: scale(1.02) !important;

    border-color: #f28c28 !important;

    background: #fff8f0 !important;
}


/* =========================================================
   DESCRIPTION CONTAINER
   ========================================================= */

.related-bottom {
    grid-column: 2 !important;
    grid-row: 2 !important;

    width: 100% !important;

    margin: 0 !important;
    padding: 0 !important;

    align-self: center !important;

    box-sizing: border-box !important;
}


/* =========================================================
   DESCRIPTION
   ========================================================= */

.related-description {
    width: 100% !important;

    max-width: 100% !important;

    margin: 0 !important;
    padding: 0 !important;

    color: #31526b !important;

    font-size: 13px !important;

    line-height: 1.5 !important;

    font-weight: 400 !important;

    text-align: left !important;
}


/* =========================================================
   REMOVE BUILDER DEFAULT SPACING
   ========================================================= */

.related-product,
.related-product > div,
.related-product > section,
.related-product p,
.related-product h1,
.related-product h2,
.related-product h3,
.related-product h4,
.related-product h5,
.related-product h6 {
    box-sizing: border-box !important;

    margin-top: 0 !important;
}


/* =========================================================
   CATEGORY HOVER
   ========================================================= */

.related-product:hover .related-eyebrow-text {
    color: #f28c28 !important;
}


/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 900px) {

    #related-products {
        width: 94% !important;

        max-width: 94% !important;

        padding: 24px !important;

        grid-template-columns: repeat(2, minmax(0, 1fr)) !important;

        gap: 18px !important;
    }


    .related-product {
        padding: 20px !important;

        column-gap: 16px !important;
    }


    .related-title {
        font-size: 25px !important;
    }


    .related-image {
        height: 175px !important;
    }
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 650px) {

    #related-products {
        width: 94% !important;

        max-width: 94% !important;

        padding: 18px !important;

        grid-template-columns: 1fr !important;

        gap: 18px !important;
    }


    .related-product {
        width: 100% !important;

        padding: 20px !important;

        grid-template-columns: 1fr 1fr !important;
    }


    .related-title {
        font-size: 25px !important;
    }


    .related-image {
        height: 180px !important;
    }


    .related-description {
        font-size: 13px !important;
    }
}


/* =========================================================
   SMALL MOBILE
   ========================================================= */

@media (max-width: 420px) {

    #related-products {
        padding: 14px !important;
    }


    .related-product {
        padding: 16px !important;

        column-gap: 12px !important;
    }


    .related-title {
        font-size: 22px !important;
    }


    .related-image {
        height: 155px !important;
    }
}

/* =========================================================
   MARSOL CAREERS PAGE
   CLEAN REFERENCE LAYOUT
   ========================================================= */


/* =========================================================
   GLOBAL
   ========================================================= */

html,
body {
    margin: 0 !important;
    padding: 0 !important;

    background: #FAFAF7 !important;
    color: #14140F !important;

    font-family: Inter, Arial, sans-serif !important;
}

* {
    box-sizing: border-box !important;
}


/* =========================================================
   CAREERS HERO
   ========================================================= */

.careers-hero {
    width: 100% !important;
    max-width: 100% !important;

    margin: 0 !important;

    /*
       Reduced bottom space so the jobs
       section follows naturally.
    */
    padding: 78px 32px 48px !important;

    background: #FAFAF7 !important;

    height: auto !important;
    min-height: 0 !important;

    box-sizing: border-box !important;

    overflow: visible !important;
}


/* =========================================================
   HERO CONTAINER
   ========================================================= */

.careers-hero-container {
    width: 100% !important;

    max-width: 1220px !important;

    margin-left: auto !important;
    margin-right: auto !important;

    padding: 0 !important;

    height: auto !important;
    min-height: 0 !important;

    box-sizing: border-box !important;
}


/* =========================================================
   HERO STACK
   ========================================================= */

.careers-hero-stack {
    width: 100% !important;

    max-width: 100% !important;

    margin: 0 !important;
    padding: 0 !important;

    height: auto !important;
    min-height: 0 !important;

    display: flex !important;

    flex-direction: column !important;

    align-items: flex-start !important;
    justify-content: flex-start !important;

    /*
       IMPORTANT:
       Prevent Builder from creating
       a large vertical gap.
    */
    gap: 0 !important;

    box-sizing: border-box !important;
}


/* =========================================================
   EYEBROW
   ========================================================= */

.careers-eyebrow {
    display: flex !important;

    align-items: center !important;

    gap: 9px !important;

    width: auto !important;

    height: auto !important;
    min-height: 0 !important;

    margin: 0 0 24px 0 !important;
    padding: 0 !important;

    font-size: 11px !important;

    font-weight: 600 !important;

    line-height: 1.3 !important;

    letter-spacing: 0.14em !important;

    text-transform: uppercase !important;

    color: #164F91 !important;

    box-sizing: border-box !important;
}


/* =========================================================
   EYEBROW DOTS
   ========================================================= */

.careers-eyebrow::before {
    content: "" !important;

    width: 7px !important;
    height: 7px !important;

    min-width: 7px !important;
    min-height: 7px !important;

    flex-shrink: 0 !important;

    border-radius: 50% !important;

    background: #F97316 !important;

    box-shadow: 15px 0 0 #7E9B1C !important;

    margin-right: 15px !important;
}


/* =========================================================
   CAREERS TITLE
   ========================================================= */

.careers-title {
    width: 100% !important;

    max-width: 900px !important;

    height: auto !important;
    min-height: 0 !important;

    margin: 0 !important;
    padding: 0 !important;

    font-family: "Space Grotesk", Inter, Arial, sans-serif !important;

    font-size: clamp(52px, 6vw, 78px) !important;

    font-weight: 500 !important;

    line-height: 1.02 !important;

    letter-spacing: -0.045em !important;

    color: #14140F !important;

    box-sizing: border-box !important;
}


/* =========================================================
   HERO SUBTITLE
   ========================================================= */

.careers-subtitle {
    width: 100% !important;

    max-width: 700px !important;

    height: auto !important;
    min-height: 0 !important;

    margin: 24px 0 0 0 !important;
    padding: 0 !important;

    font-family: Inter, Arial, sans-serif !important;

    font-size: 17px !important;

    font-weight: 400 !important;

    line-height: 1.6 !important;

    letter-spacing: 0 !important;

    color: #66747D !important;

    box-sizing: border-box !important;
}


/* =========================================================
   FORCE INNER BUILDER TEXT
   ========================================================= */

.careers-eyebrow *,
.careers-eyebrow p,
.careers-eyebrow span,
.careers-eyebrow div {

    margin: 0 !important;
    padding: 0 !important;

    font-size: 11px !important;

    line-height: 1.3 !important;

    font-weight: 600 !important;

    letter-spacing: 0.14em !important;

    text-transform: uppercase !important;

    color: #164F91 !important;
}


.careers-title *,
.careers-title p,
.careers-title span,
.careers-title div,
.careers-title h1,
.careers-title h2,
.careers-title h3 {

    margin: 0 !important;
    padding: 0 !important;

    font-family: "Space Grotesk", Inter, Arial, sans-serif !important;

    font-size: inherit !important;

    line-height: 1.02 !important;

    font-weight: 500 !important;

    letter-spacing: -0.045em !important;

    color: #14140F !important;
}


.careers-subtitle *,
.careers-subtitle p,
.careers-subtitle span,
.careers-subtitle div {

    margin: 0 !important;
    padding: 0 !important;

    font-family: Inter, Arial, sans-serif !important;

    font-size: 17px !important;

    line-height: 1.6 !important;

    font-weight: 400 !important;

    color: #66747D !important;
}


/* =========================================================
   JOBS SECTION
   ========================================================= */

.jobs-section {
    width: 100% !important;
    max-width: 100% !important;

    margin: 0 !important;

    /*
       Small top spacing only.
       No huge gap.
    */
    padding: 24px 32px 90px !important;

    background: #FAFAF7 !important;

    height: auto !important;
    min-height: 0 !important;

    box-sizing: border-box !important;
}


/* =========================================================
   JOBS CONTAINER
   ========================================================= */

.jobs-container {
    width: 100% !important;

    max-width: 1220px !important;

    margin-left: auto !important;
    margin-right: auto !important;

    padding: 0 !important;

    height: auto !important;
    min-height: 0 !important;

    box-sizing: border-box !important;
}


/* =========================================================
   HIDE "OPEN POSITIONS"

   Reference design goes directly from hero
   into the job list.

   IMPORTANT:
   This only hides the heading.
   It does NOT affect the DocType/repeater.
   ========================================================= */

.jobs-title {
    display: none !important;

    height: 0 !important;
    min-height: 0 !important;

    margin: 0 !important;
    padding: 0 !important;

    border: none !important;
}


/* =========================================================
   JOB REPEATER
   ========================================================= */

.job-repeater {
    width: 100% !important;

    max-width: 1220px !important;

    height: auto !important;
    min-height: 0 !important;

    margin: 0 auto !important;
    padding: 0 !important;

    display: flex !important;

    flex-direction: column !important;

    align-items: stretch !important;

    gap: 0 !important;

    background: transparent !important;

    box-sizing: border-box !important;
}


/* =========================================================
   JOB CARD
   ========================================================= */

.job-repeater .job-card,
.job-card {
    position: relative !important;

    width: 100% !important;
    max-width: 100% !important;

    height: auto !important;
    min-height: 0 !important;

    margin: 0 !important;

    /*
       Reference-style job row.
    */
    padding: 30px 0 !important;

    display: flex !important;

    flex-direction: column !important;

    justify-content: center !important;

    align-items: flex-start !important;

    background: transparent !important;

    border: none !important;

    border-top: 1px solid #D9DEDF !important;

    border-bottom: none !important;

    border-radius: 0 !important;

    box-shadow: none !important;

    overflow: visible !important;

    box-sizing: border-box !important;

    /*
       Keep existing hover functionality.
    */
    transition:
        background-color 0.25s ease,
        padding-left 0.25s ease !important;
}


/* =========================================================
   LAST JOB CARD
   ========================================================= */

.job-repeater .job-card:last-child {
    border-bottom: 1px solid #D9DEDF !important;
}


/* =========================================================
   JOB HOVER
   ========================================================= */

.job-card:hover {
    background: rgba(249, 115, 22, 0.035) !important;

    padding-left: 18px !important;

    cursor: pointer !important;
}


/* =========================================================
   ORANGE HOVER LINE
   ========================================================= */

.job-card::before {
    content: "" !important;

    position: absolute !important;

    left: 0 !important;
    top: 0 !important;
    bottom: 0 !important;

    width: 3px !important;

    background: #F97316 !important;

    opacity: 0 !important;

    transform: scaleY(0) !important;

    transform-origin: center !important;

    transition:
        opacity 0.25s ease,
        transform 0.25s ease !important;
}


.job-card:hover::before {
    opacity: 1 !important;

    transform: scaleY(1) !important;
}


/* =========================================================
   JOB TITLE
   ========================================================= */

.job-title {
    width: 100% !important;

    height: auto !important;
    min-height: 0 !important;

    margin: 0 0 4px 0 !important;
    padding: 0 !important;

    font-family: "Arial Narrow", "Roboto Condensed",
                 Inter, Arial, sans-serif !important;

    font-size: 22px !important;

    font-weight: 600 !important;

    line-height: 1.25 !important;

    letter-spacing: -0.02em !important;

    color: #102131 !important;

    transition: color 0.2s ease !important;
}


/* =========================================================
   JOB TITLE HOVER
   ========================================================= */

.job-card:hover .job-title {
    color: #F97316 !important;
}


/* =========================================================
   LOCATION
   ========================================================= */

.job-location {
    width: 100% !important;

    height: auto !important;
    min-height: 0 !important;

    margin: 0 !important;
    padding: 0 !important;

    font-family: Inter, Arial, sans-serif !important;

    font-size: 15px !important;

    font-weight: 400 !important;

    line-height: 1.5 !important;

    color: #68747C !important;
}


/* =========================================================
   EMPLOYMENT TYPE
   ========================================================= */

.job-type {
    width: 100% !important;

    height: auto !important;
    min-height: 0 !important;

    margin: 0 !important;
    padding: 0 !important;

    font-family: Inter, Arial, sans-serif !important;

    font-size: 15px !important;

    font-weight: 400 !important;

    line-height: 1.5 !important;

    color: #68747C !important;
}


/* =========================================================
   DESCRIPTION
   ========================================================= */

.job-description {
    width: 100% !important;

    max-width: 750px !important;

    height: auto !important;
    min-height: 0 !important;

    margin: 10px 0 0 0 !important;
    padding: 0 !important;

    font-size: 14px !important;

    line-height: 1.6 !important;

    color: #68747C !important;
}


/* =========================================================
   JOB TEXT ALIGNMENT
   ========================================================= */

.job-card .job-title,
.job-card .job-location,
.job-card .job-type,
.job-card .job-description {

    margin-left: 0 !important;
    padding-left: 0 !important;
}


/* =========================================================
   REMOVE BUILDER HEIGHT / SPACING
   ========================================================= */

.careers-hero *,
.careers-hero *::before,
.careers-hero *::after,
.jobs-section *,
.jobs-section *::before,
.jobs-section *::after {

    box-sizing: border-box !important;
}


.careers-hero-container > *,
.careers-hero-stack > *,
.jobs-container > *,
.job-repeater > *,
.job-repeater > div {

    height: auto !important;

    min-height: 0 !important;

    margin-top: 0 !important;
}


/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 900px) {

    .careers-hero {
        padding: 65px 24px 40px !important;
    }


    .careers-hero-container {
        max-width: 100% !important;
    }


    .careers-title {
        font-size: 58px !important;
    }


    .careers-subtitle {
        max-width: 650px !important;

        font-size: 16px !important;
    }


    .jobs-section {
        padding: 18px 24px 70px !important;
    }


    .jobs-container,
    .job-repeater {
        max-width: 100% !important;
    }


    .job-card {
        padding: 26px 0 !important;
    }


    .job-card:hover {
        padding-left: 12px !important;
    }
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 600px) {

    .careers-hero {
        padding: 50px 20px 35px !important;
    }


    .careers-eyebrow {
        margin-bottom: 20px !important;

        font-size: 10px !important;
    }


    .careers-eyebrow *,
    .careers-eyebrow p,
    .careers-eyebrow span,
    .careers-eyebrow div {

        font-size: 10px !important;

        letter-spacing: 0.13em !important;
    }


    .careers-title {
        max-width: 100% !important;

        font-size: 46px !important;

        line-height: 1.04 !important;

        letter-spacing: -0.04em !important;
    }


    .careers-subtitle {
        max-width: 100% !important;

        margin-top: 20px !important;

        font-size: 15px !important;

        line-height: 1.6 !important;
    }


    .careers-subtitle *,
    .careers-subtitle p,
    .careers-subtitle span,
    .careers-subtitle div {

        font-size: 15px !important;

        line-height: 1.6 !important;
    }


    .jobs-section {
        padding: 12px 20px 55px !important;
    }


    .job-card {
        padding: 22px 0 !important;
    }


    .job-card:hover {
        padding-left: 10px !important;
    }


    .job-title {
        font-size: 19px !important;

        line-height: 1.3 !important;
    }


    .job-location,
    .job-type {

        font-size: 13px !important;

        line-height: 1.5 !important;
    }


    .job-description {
        font-size: 13px !important;
    }
}


/* =========================================================
   SAFETY — DO NOT BREAK DYNAMIC JOB CONTENT
   ========================================================= */

.job-repeater,
.job-repeater > *,
.job-card,
.job-card > * {

    height: auto !important;

    min-height: 0 !important;

    max-height: none !important;
}
/* =========================================================
   MARSOL CAREERS — APPLY BUTTON
   ========================================================= */


/* =========================================================
   OUTER APPLY BUTTON
   Class: apply-button
   ========================================================= */

.job-card .apply-button {

    position: absolute !important;

    right: 0 !important;

    top: 50% !important;

    transform: translateY(-50%) !important;

    width: auto !important;

    height: auto !important;

    min-height: 0 !important;

    margin: 0 !important;

    padding: 0 !important;

    display: block !important;

    background: transparent !important;

    border: none !important;

    border-radius: 0 !important;

    box-shadow: none !important;

    text-decoration: none !important;

    cursor: pointer !important;

    box-sizing: border-box !important;

    transition: none !important;
}


/* =========================================================
   APPLY TEXT
   Class: apply-text
   ========================================================= */

.job-card .apply-button .apply-text {

    display: inline-block !important;

    width: auto !important;

    height: auto !important;

    min-height: 0 !important;

    margin: 0 !important;

    padding: 0 !important;

    background: transparent !important;

    border: none !important;

    box-shadow: none !important;

    font-family: Inter, Arial, sans-serif !important;

    font-size: 16px !important;

    font-weight: 500 !important;

    line-height: 1.4 !important;

    letter-spacing: 0 !important;

    color: #F97316 !important;

    text-decoration: none !important;

    white-space: nowrap !important;

    box-sizing: border-box !important;

    transition: color 0.2s ease !important;
}


/* =========================================================
   FORCE INNER TEXT
   ========================================================= */

.job-card .apply-button .apply-text *,
.job-card .apply-button .apply-text p,
.job-card .apply-button .apply-text span,
.job-card .apply-button .apply-text div {

    margin: 0 !important;

    padding: 0 !important;

    font-family: Inter, Arial, sans-serif !important;

    font-size: 16px !important;

    font-weight: 500 !important;

    line-height: 1.4 !important;

    letter-spacing: 0 !important;

    color: #F97316 !important;

    background: transparent !important;

    border: none !important;

    text-decoration: none !important;
}


/* =========================================================
   ARROW
   ========================================================= */

.job-card .apply-text::after {

    content: " →" !important;

    display: inline-block !important;

    color: #F97316 !important;

    font-size: 17px !important;

    margin-left: 2px !important;

    transition: transform 0.2s ease !important;
}


/* =========================================================
   HOVER — APPLY
   ========================================================= */

.job-card .apply-button:hover .apply-text,
.job-card .apply-button:hover .apply-text * {

    color: #D85E0B !important;

    text-decoration: none !important;
}


.job-card .apply-button:hover .apply-text::after {

    color: #D85E0B !important;

    transform: translateX(4px) !important;
}


/* =========================================================
   IMPORTANT
   JOB CARD HOVER MUST NOT MOVE APPLY
   ========================================================= */

.job-card:hover .apply-button {

    transform: translateY(-50%) !important;
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 600px) {

    .job-card .apply-button {

        position: static !important;

        transform: none !important;

        width: auto !important;

        height: auto !important;

        margin-top: 10px !important;

        display: block !important;
    }


    .job-card .apply-button .apply-text,
    .job-card .apply-button .apply-text * {

        font-size: 14px !important;

        line-height: 1.4 !important;
    }


    .job-card .apply-button .apply-text::after {

        font-size: 15px !important;
    }


    .job-card:hover .apply-button {

        transform: none !important;
    }
}

(() => {
    const root = document.documentElement, KEY = "builder-theme";
    const system = () => window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
    root.setAttribute("data-theme", localStorage.getItem(KEY) || system());
    document.addEventListener("click", (e) => {
        const t = e.target.closest("[data-theme-toggle]");
        if (!t) return;
        const next = root.getAttribute("data-theme") === "dark" ? "light" : "dark";
        root.setAttribute("data-theme", next);
        localStorage.setItem(KEY, next);
    });
})();

[data-theme-toggle]{cursor:pointer;transition:background-color .15s ease-out;}
[data-theme-toggle] .ti-sun{display:none;}
[data-theme-toggle] .ti-moon{display:inline-flex;}
:root[data-theme="dark"] [data-theme-toggle] .ti-sun{display:inline-flex;}
:root[data-theme="dark"] [data-theme-toggle] .ti-moon{display:none;}

