// Marsol Gemini Chatbot

document.addEventListener("DOMContentLoaded", function () {

    // Find the Chat with Marsol button
    const chatButton = document.querySelector(".marsol-chat-button");

    if (!chatButton) {
        console.log("Marsol chat button not found");
        return;
    }

    // Prevent duplicate chatbot
    if (document.getElementById("marsol-chat-box")) {
        return;
    }

    // ==============================
    // CREATE CHAT WINDOW
    // ==============================

    const chatBox = document.createElement("div");

    chatBox.id = "marsol-chat-box";

    chatBox.innerHTML = `
        <div class="marsol-chat-header">
            <span>🤖 Marsol Assistant</span>
            <button id="marsol-chat-close">×</button>
        </div>

        <div id="marsol-chat-messages">

            <div class="marsol-bot-message">
                Hi! 👋 I'm Marsol's AI assistant.
                <br><br>
                How can I help you today?
            </div>

        </div>

        <div class="marsol-chat-input-area">

            <input
                id="marsol-chat-input"
                type="text"
                placeholder="Ask something..."
                autocomplete="off"
            />

            <button id="marsol-chat-send">
                ➤
            </button>

        </div>
    `;

    document.body.appendChild(chatBox);


    // ==============================
    // CHATBOT CSS
    // ==============================

    const style = document.createElement("style");

    style.textContent = `

        #marsol-chat-box {

            position: fixed;

            right: 25px;
            bottom: 90px;

            width: 350px;
            height: 450px;

            background: #111;

            border: 1px solid #333;

            border-radius: 16px;

            z-index: 99999;

            display: none;

            flex-direction: column;

            overflow: hidden;

            box-shadow:
                0 10px 40px rgba(0,0,0,0.5);

            font-family: Arial, sans-serif;
        }


        /* HEADER */

        .marsol-chat-header {

            background: #cfff32;

            color: #111;

            padding: 16px;

            font-weight: bold;

            display: flex;

            justify-content: space-between;

            align-items: center;
        }


        .marsol-chat-header button {

            border: none;

            background: transparent;

            font-size: 25px;

            cursor: pointer;

            color: #111;
        }


        /* MESSAGE AREA */

        #marsol-chat-messages {

            flex: 1;

            padding: 15px;

            overflow-y: auto;

            color: white;

            background: #111;
        }


        /* BOT MESSAGE */

        .marsol-bot-message {

            background: #222;

            color: white;

            padding: 10px 12px;

            margin-bottom: 10px;

            border-radius: 10px;

            max-width: 85%;

            line-height: 1.4;

            word-wrap: break-word;
        }


        /* USER MESSAGE */

        .marsol-user-message {

            background: #cfff32;

            color: #111;

            padding: 10px 12px;

            margin-bottom: 10px;

            border-radius: 10px;

            max-width: 85%;

            margin-left: auto;

            line-height: 1.4;

            word-wrap: break-word;
        }


        /* INPUT AREA */

        .marsol-chat-input-area {

            display: flex;

            padding: 10px;

            border-top: 1px solid #333;

            gap: 8px;

            background: #111;
        }


        #marsol-chat-input {

            flex: 1;

            padding: 11px;

            border-radius: 8px;

            border: 1px solid #444;

            background: #222;

            color: white;

            outline: none;

            font-size: 14px;
        }


        #marsol-chat-input::placeholder {

            color: #999;
        }


        #marsol-chat-send {

            width: 45px;

            border: none;

            border-radius: 8px;

            background: #cfff32;

            color: #111;

            cursor: pointer;

            font-size: 18px;
        }


        #marsol-chat-send:hover {

            opacity: 0.85;
        }


        /* MOBILE */

        @media (max-width: 600px) {

            #marsol-chat-box {

                right: 10px;

                bottom: 80px;

                width: calc(100% - 20px);

                height: 450px;
            }
        }

    `;

    document.head.appendChild(style);


    // ==============================
    // OPEN CHATBOT
    // ==============================

    chatButton.addEventListener("click", function (event) {

        event.preventDefault();

        chatBox.style.display = "flex";

        const input =
            document.getElementById("marsol-chat-input");

        if (input) {

            input.focus();

        }

    });


    // ==============================
    // CLOSE CHATBOT
    // ==============================

    document
        .getElementById("marsol-chat-close")
        .addEventListener("click", function () {

            chatBox.style.display = "none";

        });


    // ==============================
    // SEND MESSAGE
    // ==============================

    async function sendMessage() {

        const input =
            document.getElementById("marsol-chat-input");

        const messages =
            document.getElementById("marsol-chat-messages");

        const message =
            input.value.trim();


        // Don't send empty messages

        if (!message) {

            return;

        }


        // ==============================
        // SHOW USER MESSAGE
        // ==============================

        const userMessage =
            document.createElement("div");

        userMessage.className =
            "marsol-user-message";

        userMessage.textContent =
            message;

        messages.appendChild(userMessage);


        // Clear input

        input.value = "";


        // ==============================
        // SHOW LOADING
        // ==============================

        const loading =
            document.createElement("div");

        loading.id =
            "marsol-loading";

        loading.className =
            "marsol-bot-message";

        loading.textContent =
            "Thinking... 🤔";

        messages.appendChild(loading);


        messages.scrollTop =
            messages.scrollHeight;


        // ==============================
        // CALL FRAPPE + GEMINI API
        // ==============================

        try {

            const response = await fetch(

                "/api/method/marsol_website.api.chatbot.chat?message=" +
                encodeURIComponent(message),

                {

                    method: "GET",

                    credentials: "same-origin"

                }

            );


            // Check HTTP status

            if (!response.ok) {

                throw new Error(
                    "API request failed: " +
                    response.status
                );

            }


            // Convert response to JSON

            const result =
                await response.json();


            console.log(
                "Marsol Gemini response:",
                result
            );


            // Remove loading message

            if (loading) {

                loading.remove();

            }


            // Get Gemini response

            const reply =
                result.message?.reply;


            if (!reply) {

                throw new Error(
                    "No reply received from API"
                );

            }


            // ==============================
            // SHOW BOT RESPONSE
            // ==============================

            const botMessage =
                document.createElement("div");

            botMessage.className =
                "marsol-bot-message";

            botMessage.textContent =
                reply;

            messages.appendChild(
                botMessage
            );


            messages.scrollTop =
                messages.scrollHeight;


        }

        catch (error) {

            console.error(
                "Marsol chatbot error:",
                error
            );


            // Remove loading

            if (loading) {

                loading.remove();

            }


            // Show error

            const errorMessage =
                document.createElement("div");

            errorMessage.className =
                "marsol-bot-message";

            errorMessage.textContent =
                "Sorry, I couldn't connect to the assistant. Please try again.";

            messages.appendChild(
                errorMessage
            );


            messages.scrollTop =
                messages.scrollHeight;

        }

    }


    // ==============================
    // SEND BUTTON
    // ==============================

    document
        .getElementById("marsol-chat-send")
        .addEventListener(
            "click",
            sendMessage
        );


    // ==============================
    // ENTER KEY
    // ==============================

    document
        .getElementById("marsol-chat-input")
        .addEventListener(
            "keydown",
            function (event) {

                if (event.key === "Enter") {

                    event.preventDefault();

                    sendMessage();

                }

            }
        );

});

