        border:none;
        background:none;
        font-size:22px;
        cursor:pointer;
    }


    #marsol-search-input {

        width:100%;
        padding:12px;
        border:1px solid #ccc;
        border-radius:8px;
        margin-bottom:10px;
        box-sizing:border-box;

    }


    #marsol-search-submit {

        width:100%;
        padding:12px;
        background:#cfff32;
        border:none;
        border-radius:8px;
        font-weight:bold;
        cursor:pointer;

    }


    #marsol-search-results {

        margin-top:15px;

    }


    .marsol-result {

        padding:12px;
        border-bottom:1px solid #ddd;
        cursor:pointer;

    }


    .marsol-result:hover {

        background:#f3f3f3;

